-- Dados no formato anterior à migração de mesmo nome, gravados pelo `npm run test:db` logo antes dela,
-- como numa instância já em uso. deal-lifecycle.sql confere o backfill sobre estes registros.
-- Sem gatilhos (session_replication_role=replica) para fixar datas de criação e de histórico.
-- Uma organização própria, sem membros dos demais testes: a RLS a esconde das outras verificações.
set session_replication_role=replica;
-- 1: criada em agosto, ganha em 05/10 e movida de etapa já ganha em 07/10; probabilidade antiga fora do padrão.
-- 2: perdida em 15/09. 3: ganha, reaberta e ganha de novo em 25/09. 4: criada já ganha.
-- 5: aberta com a probabilidade da etapa. 6: aberta com valor manual. 7: aberta herdando. 8: ganha sem histórico.
set session_replication_role=default;
